import bodyParser from 'body-parser';
import express from 'express';
import { Server } from 'http';
import { AddressInfo } from 'net';
import util from 'util';
import orderService from '../business-logic/order-service';
import { errorHandler } from '../error-handling';
import { authenticationMiddleware } from '../libraries/authentication-middleware';

let connection: Server | null = null;

export const startWebServer = (): Promise<AddressInfo> => {
  return new Promise<AddressInfo>((resolve, reject) => {
    const expressApp = express();
    expressApp.use(
      bodyParser.urlencoded({
        extended: true,
      }),
    );
    expressApp.use(bodyParser.json());
    expressApp.use(authenticationMiddleware);
    defineRoutes(expressApp);
    // ️️️✅ Best Practice 8.13: Specify no port for testing, only in production
    // 📖 Read more at: bestpracticesnodejs.com/bp/8.13
    const webServerPort = process.env.PORT ? process.env.PORT : null;
    connection = expressApp.listen(webServerPort, () => {
      resolve(connection!.address() as AddressInfo);
    });
  });
};

export const stopWebServer = async () => {
  return new Promise<void>((resolve, reject) => {
    if (connection) {
      connection.close(() => {
        return resolve();
      });
    }
    return resolve();
  });
};

const defineRoutes = (expressApp: express.Application) => {
  const router = express.Router();

  // add new order
  router.post(
    '/',
    async (
      req: express.Request,
      res: express.Response,
      next: express.NextFunction,
    ) => {
      try {
        console.log(
          `Order API was called to add new Order ${util.inspect(req.body)}`,
        );
        const addOrderResponse = await orderService.addOrder(req.body);
        return res.json(addOrderResponse);
      } catch (error) {
        next(error);
      }
    },
  );

  // get existing order by id
  router.get('/:id', async (req, res, next) => {
    console.log(`Order API was called to get order by id ${req.params.id}`);
    const response = await orderService.getOrder(req.params.id);

    if (!response) {
      res.status(404).end();
      return;
    }

    res.json(response);
  });

  expressApp.use('/order', router);

  expressApp.use(
    //An error can be any unknown thing, this is why we're being careful here
    async (
      error: unknown,
      _req: express.Request,
      res: express.Response,
      _next: express.NextFunction,
    ) => {
      if (!error || typeof error !== 'object') {
        await errorHandler.handleError(error);
        return res.status(500).end();
      }
      const status = 'status' in error ? error.status : 500;
      const richError = error as Record<string, unknown>;
      if (!('isTrusted' in error)) {
        //Error during a specific request is usually not catastrophic and should not lead to process exit
        richError.isTrusted = true;
      }
      await errorHandler.handleError(richError);
      res.status(status as number).end();
    },
  );
};

process.on('uncaughtException', (error) => {
  errorHandler.handleError(error);
});

process.on('unhandledRejection', (reason) => {
  errorHandler.handleError(reason);
});
const util = require('util');
const axios = require('axios').default;
const mailer = require('../libraries/mailer');
const axiosRetry = require('axios-retry').default;
const OrderRepository = require('../data-access/order-repository');
const { AppError } = require('../error-handling');
const MessageQueueClient = require('../libraries/message-queue-client');
const { AxiosError } = require('axios');

const axiosHTTPClient = axios.create({});

module.exports.addOrder = async function (newOrder) {
  // validation
  if (!newOrder.productId) {
    throw new AppError('invalid-order', `No product-id specified`, 400);
  }

  // verify user existence by calling external Microservice
  const userWhoOrdered = await getUserFromUsersService(newOrder.userId);
  console.log('userWhoOrdered', userWhoOrdered);
  if (!userWhoOrdered) {
    console.log('The user was not found');
    throw new AppError(
      'user-doesnt-exist',
      `The user ${newOrder.userId} doesnt exist`,
      404,
    );
  }

  // A little logic to calculate the total price
  if (newOrder.isPremiumUser) {
    newOrder.totalPrice = Math.ceil(newOrder.totalPrice * 0.9);
  }

  // save to DB (Caution: simplistic code without layers and validation)
  const DBResponse = await new OrderRepository().addOrder(newOrder);

  console.log('DBResponse', DBResponse);
  if (process.env.SEND_MAILS === 'true') {
    await mailer.send(
      'New order was placed',
      `user ${DBResponse.userId} ordered ${DBResponse.productId}`,
      'admin@app.com',
    );
  }

  // We should notify others that a new order was added - Let's put a message in a queue
  await new MessageQueueClient().publish(
    'order.events',
    'order.events.new',
    newOrder,
  );

  return DBResponse;
};

module.exports.deleteOrder = async function (id) {
  return await new OrderRepository().deleteOrder(id);
};

module.exports.getOrder = async function (id) {
  return await new OrderRepository().getOrderById(id);
};

async function getUserFromUsersService(userId) {
  try {
    const getUserResponse = await axiosHTTPClient.get(
      `http://localhost/user/${userId}`,
      {
        timeout: process.env.HTTP_TIMEOUT
          ? parseInt(process.env.HTTP_TIMEOUT)
          : 2000,
        validateStatus: (status) => {
          return status < 500;
        },
      },
    );
    return getUserResponse.data;
  } catch (error) {
    if (error?.code === 'ECONNABORTED') {
      throw new AppError(
        'user-verification-failed',
        `Request to user service failed so user cant be verified`,
        503,
      );
    }

    throw error;
  }
}
const Sequelize = require('sequelize');
const sequelizeConfig = require('./config/config');

let repository;
let orderModel;

module.exports = class OrderRepository {
  constructor() {
    if (!repository) {
      repository = new Sequelize(
        'shop',
        'myuser',
        'myuserpassword',
        sequelizeConfig,
      );
      orderModel = repository.define('Order', {
        id: {
          type: Sequelize.INTEGER,
          primaryKey: true,
          autoIncrement: true,
        },
        externalIdentifier: {
          type: Sequelize.STRING,
          unique: true,
          allowNull: true,
        },
        mode: {
          type: Sequelize.STRING,
        },
        userId: {
          type: Sequelize.INTEGER,
        },
        contactEmail: {
          type: Sequelize.STRING,
        },
        productId: {
          type: Sequelize.INTEGER,
        },
        totalPrice: {
          type: Sequelize.INTEGER,
        },
        isPremiumUser: {
          type: Sequelize.BOOLEAN,
        },
      });
    }
  }

  async getOrderById(id) {
    return await orderModel.findOne({ where: { id } });
  }

  async addOrder(orderDetails) {
    const addingResponse = await orderModel.create(orderDetails);

    return addingResponse.dataValues;
  }

  async deleteOrder(orderToDelete) {
    await orderModel.destroy({ where: { id: orderToDelete } });
    return;
  }

  async cleanup() {
    await orderModel.truncate();
  }
};
