      resolve(connection!.address() as AddressInfo);
    });
  });
};

export const stopWebServer = async () => {
  return new Promise<void>((resolve, reject) => {
    if (connection) {
      connection.close(() => {
        return resolve();
      });
    }
    return resolve();
  });
};

