  testSetup.tearDownTestFile();
});

describe('DELETE /order/:id', () => {
  test('When deleting an existing order, Then should get back 204 with empty body', async () => {
    //Arrange
    const {
      data: { id: orderId },
    } = await testSetup.getHTTPClient().post('/order', buildOrder());

    //Act
    const deleteResponse = await testSetup
      .getHTTPClient()
      .delete(`/order/${orderId}`);

    //Assert
    expect(deleteResponse).toMatchObject({ status: 204, data: '' });
  });

  test('When deleting an existing order, Then it should no longer be retrievable', async () => {
    //Arrange
    const {
      data: { id: orderId },
    } = await testSetup.getHTTPClient().post('/order', buildOrder());

    //Act
    await testSetup.getHTTPClient().delete(`/order/${orderId}`);

    //Assert
    const getResponse = await testSetup
      .getHTTPClient()
      .get(`/order/${orderId}`);
    expect(getResponse.status).toBe(404);
  });

  test('When deleting an order, Then other orders remain unaffected', async () => {
    //Arrange
    const {
      data: { id: orderToDeleteId },
    } = await testSetup.getHTTPClient().post('/order', buildOrder());
    const orderToKeep = buildOrder();
    const {
      data: { id: orderToKeepId },
    } = await testSetup.getHTTPClient().post('/order', orderToKeep);

    //Act
    await testSetup.getHTTPClient().delete(`/order/${orderToDeleteId}`);

    //Assert
    const getResponse = await testSetup
      .getHTTPClient()
      .get(`/order/${orderToKeepId}`);
    expect(getResponse).toMatchObject({
      status: 200,
      data: { ...orderToKeep, id: orderToKeepId },
    });
  });
});

